using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Assets.Scripts.Game.Enum;
using Scripts.Level;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

[InitializeOnLoad]
public static class StorybookRebirthValidation
{
    public const string Out="output/rebirth-ui/";static bool started;static double deadline;
    static StorybookRebirthValidation(){EditorApplication.update+=Tick;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("REBIRTH_UI_QA",false)){SessionState.SetBool("REBIRTH_UI_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);SessionState.EraseInt("SETTINGS_QA_SKIP");started=false;}};}
    static void Tick(){if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;
        if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(Out+"validate.request")){File.Delete(Out+"validate.request");File.WriteAllText(Out+"validation.txt","Actual Unity rebirth UI validation; isolated project; player save writes disabled.\n");EditorSceneManager.OpenScene("Assets/Scenes/MainScenes/Gameplay.unity");SessionState.SetBool("REBIRTH_UI_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);SessionState.SetInt("SETTINGS_QA_SKIP",1);started=false;deadline=EditorApplication.timeSinceStartup+300;StorybookEquipmentValidation.Resolution(941,1672);EditorApplication.isPlaying=true;}
        if(EditorApplication.isPlaying&&SessionState.GetBool("REBIRTH_UI_QA",false)&&!started&&GameManager.single&&GameplayCanvas.single){started=true;deadline=EditorApplication.timeSinceStartup+300;GameManager.single.StartCoroutine(new RebirthProbe().Run());}
        if(EditorApplication.isPlaying&&SessionState.GetBool("REBIRTH_UI_QA",false)&&deadline>0&&EditorApplication.timeSinceStartup>deadline){Log("FAIL watchdog");EditorApplication.isPlaying=false;}}
    public static void Log(string s)=>File.AppendAllText(Out+"validation.txt",s+"\n");
}
public sealed class RebirthProbe
{
    int failures,errors;GameManager gm;RebirthPackage owner;StorybookRebirthUI ui;
    void Check(bool b,string s){StorybookRebirthValidation.Log((b?"PASS ":"FAIL ")+s);if(!b)failures++;}
    void Error(string m,string st,LogType t){if(t==LogType.Error||t==LogType.Exception){errors++;StorybookRebirthValidation.Log("ERROR "+m+"\n"+st);}}
    void Shot(string n){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(StorybookRebirthValidation.Out+n+".png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
    void Hit(Button b,string label){var r=(RectTransform)b.transform;var p=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=p},hits);Check(hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,label);}
    IEnumerator Open(){Router.single.CallRebirthFromCamp();yield return new WaitForSecondsRealtime(3);owner=RebirthPackage.single;ui=owner.view;ui.Refresh();}
    public IEnumerator Run(){Application.logMessageReceived+=Error;gm=GameManager.single;var gc=GameplayCanvas.single;var intro=UnityEngine.Object.FindFirstObjectByType<CursedBookIntro>(FindObjectsInactive.Include);while(intro&&!intro.Finished)yield return null;yield return new WaitForSecondsRealtime(1);
        gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);gc.dailyCherriesPop.SetActive(false);for(int i=0;i<20;i++)if(!gm.HasSeenThis("Tutorial-"+i))gm.thingsSeenPermanent.Add("Tutorial-"+i);if(TutorialManager.single){TutorialManager.single.overlay.SetActive(false);TutorialManager.single.tutorialCharacter.SetActive(false);foreach(var t in TutorialManager.single.tutorials)t.SetActive(false);}
        gm.playerLevel=60;gm.rebirthLevel=0;gm.stackedXp=gm.stackedCrystals=0;gm.premiumCurrency=123;gc.homeUI.Refresh();gc.homeUI.OpenFunction(2);gc.homeUI.modalAction.onClick.Invoke();yield return new WaitForSecondsRealtime(3);owner=RebirthPackage.single;ui=owner.view;
        Check(owner&&ui&&gm.gameState==GameStateType.REBIRTH,"home entry resolves rebuilt addressable prefab");Check(ui.GetComponentsInChildren<Transform>(true).All(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)==0),"persistent prefab has no missing scripts");Check(UnityEngine.Object.FindObjectsByType<EventSystem>(FindObjectsSortMode.None).Length==1,"one active event system");
        Check(ui.currentValues.Select(t=>t.text).SequenceEqual(new[]{"+10","+3","+50%","10,000"}),"first rebirth rewards match config");Check(ui.nextValues.Select(t=>t.text).SequenceEqual(new[]{"+10","+3","+51%","10,015"}),"next level comparison matches formulas");int nodes=ui.GetComponentsInChildren<Transform>(true).Length;
        int[] w={941,768,720},h={1672,1024,1440};string[] tags={"9x16","3x4","1x2"};
        for(int i=0;i<3;i++){StorybookEquipmentValidation.Resolution(w[i],h[i]);yield return new WaitForSecondsRealtime(.5f);while(ShaderUtil.anythingCompiling)yield return null;var layout=ui.GetComponent<StorybookFusionLayout>();layout.Apply();Canvas.ForceUpdateCanvases();yield return new WaitForEndOfFrame();Shot(tags[i]+"-ready");Hit(ui.back,tags[i]+" back clickable");Hit(ui.rebirth,tags[i]+" rebirth clickable");Hit(ui.adventure,tags[i]+" continue adventure clickable");var corners=new Vector3[4];layout.page.GetWorldCorners(corners);Check(corners.All(c=>c.x>=-1&&c.y>=-1&&c.x<=Screen.width+1&&c.y<=Screen.height+1),tags[i]+" page within viewport");ui.rebirth.onClick.Invoke();yield return new WaitForEndOfFrame();Shot(tags[i]+"-confirmation");Hit(ui.confirm,tags[i]+" confirm clickable");Hit(ui.cancel,tags[i]+" cancel clickable");Check(gm.playerLevel==60&&gm.rebirthLevel==0,"opening confirmation does not reset progress");ui.cancel.onClick.Invoke();Check(!ui.confirmation.activeSelf,"cancel closes confirmation");}
        var safe=ui.GetComponent<StorybookFusionLayout>();safe.SetValidationSafeArea(new Rect(0,60,Screen.width,Screen.height-110));yield return new WaitForEndOfFrame();Shot("1x2-safe-area");Hit(ui.back,"safe area back clickable");Hit(ui.adventure,"safe area bottom clickable");safe.SetValidationSafeArea(null);
        var feedback=ui.rebirth.GetComponent<ShelterButtonFeedback>();var scale=ui.rebirth.transform.localScale;var evt=new PointerEventData(EventSystem.current);feedback.OnPointerDown(evt);Check(ui.rebirth.transform.localScale.x<scale.x,"primary press feedback");feedback.OnPointerUp(evt);Check(ui.rebirth.transform.localScale==scale,"primary release restores");
        gm.playerLevel=59;ui.Refresh();yield return null;yield return new WaitForEndOfFrame();Check(!ui.rebirth.interactable&&!owner.CanRebirth,"under level disables rebirth");var im=ui.rebirth.GetComponent<Image>();Check(im.material.GetFloat("_DisabledUI")==1&&ui.rebirthCaption.material.GetFloat("_DisabledUI")==1,"whole primary button and text grey");Shot("locked");owner.ToggleAreYouSure(true);owner.RebirthButton();Check(!ui.confirmation.activeSelf&&gm.rebirthLevel==0,"under level cannot confirm or transact");
        gm.playerLevel=60;ui.Refresh();yield return null;yield return new WaitForEndOfFrame();Check(ui.rebirth.interactable&&im.material.GetFloat("_DisabledUI")==0,"enabled artwork restored");gm.rebirthLevel=9;gm.playerLevel=(int)LevelDataDescriptions.RebirthLevelDb[10].minLevel;ui.Refresh();Canvas.ForceUpdateCanvases();yield return new WaitForEndOfFrame();Check(ui.number.cachedTextGenerator.lineCount==1,"two-digit rebirth number fits a single line");Shot("later-rebirth");gm.rebirthLevel=LevelDataDescriptions.RebirthLevelDb.Length-1;ui.Refresh();Check(!ui.rebirth.interactable&&ui.rebirthCaption.text=="已达上限","max rebirth guarded without array overflow");Shot("max-level");gm.rebirthLevel=0;gm.playerLevel=61;gm.stackedXp=25;gm.stackedCrystals=200;ui.Refresh();Check(ui.currentValues[2].text=="+76%"&&ui.currentValues[3].text=="10,215","carryover and overlevel rewards");gm.playerLevel=60;gm.stackedXp=gm.stackedCrystals=0;ui.Refresh();
        ui.adventure.onClick.Invoke();yield return new WaitForSecondsRealtime(2);Check(gm.gameState==GameStateType.CAMP&&!RebirthPackage.single&&gm.playerLevel==60,"continue adventure returns without reset");Hit(gc.homeUI.settingsButton,"home clickable after return");
        yield return Open();ui.back.onClick.Invoke();yield return new WaitForSecondsRealtime(2);Check(gm.gameState==GameStateType.CAMP&&!RebirthPackage.single,"header back returns without orphan UI");
        yield return Open();Check(ui.GetComponentsInChildren<Transform>(true).Length==nodes,"reopen uses saved nodes without runtime construction");Router.single.loadingChestFromCamp=true;ui.rebirth.onClick.Invoke();ui.confirm.onClick.Invoke();owner.RebirthButton();Check(gm.rebirthLevel==1&&gm.playerLevel==1,"confirmed rebirth runs once and resets level");Check(gm.statPoints==10&&gm.skillPoints==3&&gm.crystals==10000&&gm.stackedXp==50,"actual rebirth grants configured rewards once");Check(gm.premiumCurrency==123,"premium currency retained");Check(gm.fusionLevel==0&&WaveManager.single.highestWavesReached.Count==0&&!InventoryManager.single.hasWeapon,"fusion equipment and wave reset preserved");Check(owner.cutsceneObj.activeSelf&&!owner.rebirthCanvas.activeSelf,"original rebirth cutscene preserved");yield return new WaitForSecondsRealtime(1.5f);yield return new WaitForEndOfFrame();Shot("rebirth-animation");yield return new WaitForSecondsRealtime(9);Check(gm.gameState==GameStateType.CAMP&&!RebirthPackage.single&&gc.homeUI.gameObject.activeInHierarchy,"rebirth animation completes and returns home");yield return new WaitForEndOfFrame();Shot("after-rebirth-home");Hit(gc.homeUI.settingsButton,"home interactive after rebirth");Check(!Router.single.loadingChestFromCamp,"rebirth return clears chest navigation latch");Check(errors==0,"no unexpected runtime errors");Application.logMessageReceived-=Error;StorybookRebirthValidation.Log((failures==0&&errors==0?"PASS":"FAIL")+" COMPLETE failures="+failures+" errors="+errors);EditorApplication.isPlaying=false;
    }
}
